using System.Text.Json;
using System.Security.Cryptography;
using Mono.Cecil;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
var task=Path.GetFullPath(args[0]);var project=Path.GetFullPath(Path.Combine(task,"outputs/OccupyCityRecovered"));var work=Path.Combine(task,"work/burst-bool-abi");var report=JsonDocument.Parse(File.ReadAllText(Path.Combine(work,"applied.json"))).RootElement;var rows=new List<object>();int bodyCount=0;
foreach(var row in report.GetProperty("files").EnumerateArray()){string rel=row.GetProperty("file").GetString()!,current=Path.Combine(project,rel),before=Path.Combine(task,"work/recovery-stubs/burst-bool-abi-before",rel);CheckHash(before,row.GetProperty("beforeSha256").GetString()!);CheckHash(current,row.GetProperty("afterSha256").GetString()!);CheckHash(current+".meta",row.GetProperty("metaSha256").GetString()!);var a=CSharpSyntaxTree.ParseText(File.ReadAllText(before)).GetRoot();var b=CSharpSyntaxTree.ParseText(File.ReadAllText(current)).GetRoot();var attrs=b.DescendantNodes().OfType<AttributeListSyntax>().Where(x=>x.ToString().Contains("global::System.Runtime.InteropServices.MarshalAs")).ToArray();if(!a.IsEquivalentTo(b.RemoveNodes(attrs,SyntaxRemoveOptions.KeepNoTrivia)!))throw new Exception("Unexpected source syntax change");var ab=a.DescendantNodes().OfType<BlockSyntax>().ToArray();var bb=b.DescendantNodes().OfType<BlockSyntax>().ToArray();if(!ab.Select(x=>x.ToString()).SequenceEqual(bb.Select(x=>x.ToString())))throw new Exception("Body changed");bodyCount+=ab.Length;rows.Add(new{file=rel,attributesAdded=attrs.Length,bodyBlocksUnchanged=ab.Length,allOtherSyntaxEquivalent=true,sourceAndBackupHashesMatched=true,metaHashMatched=true});}
var dll=Path.Combine(work,"AstarPathfindingProject.check.dll");var asm=AssemblyDefinition.ReadAssembly(dll);var all=asm.MainModule.Types.SelectMany(All).ToArray();var original=AssemblyDefinition.ReadAssembly(Path.Combine(task,"work/il2cpp-dump-decoded/DummyDll/AstarPathfindingProject.dll"));var originals=original.MainModule.Types.SelectMany(All).ToArray();var fields=all.SelectMany(t=>t.Fields).Where(f=>new[]{"0x4000EA1","0x4000EA2","0x4000896"}.Contains(Token(f))).ToArray();if(fields.Length!=3)throw new Exception("Field identity count mismatch");var metadata=fields.Select(f=>{var prior=originals.SelectMany(t=>t.Fields).Single(p=>Token(p)==Token(f));if(!f.HasMarshalInfo||f.MarshalInfo.NativeType!=NativeType.U1||f.FieldType.FullName!="System.Boolean"||Token(f.DeclaringType)!=Token(prior.DeclaringType)||!Equals(Offset(f),Offset(prior)))throw new Exception("Field metadata compatibility check failed");return new{type=f.DeclaringType.FullName,typeToken=Token(f.DeclaringType),field=f.Name,token=Token(f),originalNativeOffset=Offset(prior),originalHasMarshalInfo=prior.HasMarshalInfo,currentMarshalNativeType=f.MarshalInfo.NativeType.ToString(),fieldTypeUnchanged=true};}).ToArray();
File.WriteAllText(Path.Combine(work,"independent-verification.json"),JsonSerializer.Serialize(new{implementationRecoveryCount=0,sourceFiles=rows,unchangedBodyBlockCount=bodyCount,compiledDllSha256=Hash(dll),actualCecilFieldMarshalInfo=metadata,independentCSharpCompilationPassed=true,officialBurstRecompileRun=false,unityStarted=false,coreGameplayAccepted=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Verified {bodyCount} body blocks unchanged, only3 attribute lists added, original field/type Tokens and offsets retained; real compiler DLL contains3 NativeType.U1 MarshalInfo fields");
static IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
static string? Token(ICustomAttributeProvider p)=>p.CustomAttributes.FirstOrDefault(a=>a.AttributeType.Name=="TokenAttribute")?.Fields.FirstOrDefault(f=>f.Name=="Token").Argument.Value as string;
static object? Offset(FieldDefinition f)=>f.CustomAttributes.FirstOrDefault(a=>a.AttributeType.Name=="FieldOffsetAttribute")?.Fields.FirstOrDefault(x=>x.Name=="Offset").Argument.Value;
static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
static void CheckHash(string p,string e){if(!Hash(p).Equals(e,StringComparison.OrdinalIgnoreCase))throw new Exception("Hash mismatch "+p);}
